using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;
namespace GearLab {public static class CompoundExport {
 public static double Explode(Result r,CadPart p){var chain=CompoundReducer.Ordered(r.Train);for(int i=0;i<chain.Count;i++)if(p.Id.StartsWith(chain[i].Id+"_")||p.Id=="SH_MODULE_"+(i+1)||p.Id=="SH_PARTITION_"+(i+1)||p.Id=="SH_BEARING_"+(i+1)||p.Id=="SH_JOINT_"+(i+1))return (i+1)*24;if(p.Id=="SH_COVER"||p.Id=="SH_BEARING_COVER")return (chain.Count+1)*24;return 0;}
 public static void PrintZip(TransmissionTrain t,TrainSolution s,string path){if(!CompoundReducer.Enabled(t)){PrintExport.Zip(PrintExport.Select(s.Scene.Model,null),path);return;}string temp=path+"."+Guid.NewGuid().ToString("N")+".zip";try{PrintExport.Zip(PrintExport.Select(s.Scene.Model,null),temp);using(var zip=ZipFile.Open(temp,ZipArchiveMode.Update)){var bom=new StringBuilder("Id;Part;Role;Quantity;Volume_mm3;Material;Density_kg_m3;Mass_kg;Source;Preliminary\r\n");foreach(var q in s.Scene.Model.Parts.Where(q=>!q.Reference))bom.AppendLine(q.Id+";\""+q.Label.Replace("\"","\"\"")+"\";"+q.Role+";1;"+CadNumbers.F(q.Volume())+";\""+(q.MaterialName??"legacy").Replace("\"","\"\"")+"\";"+CadNumbers.F(q.MaterialDensity>0?q.MaterialDensity:q.Role=="housing"?1250:7850)+";"+CadNumbers.F(q.Volume()*1e-9*(q.MaterialDensity>0?q.MaterialDensity:q.Role=="housing"?1250:7850))+";\""+(q.MaterialSource??"").Replace("\"","\"\"")+"\";ReadyForManufacture=false");using(var w=new StreamWriter(zip.CreateEntry("BOM_all_parts.csv").Open(),new UTF8Encoding(true)))w.Write(bom);using(var w=new StreamWriter(zip.CreateEntry("compound.train.json").Open(),Encoding.UTF8))w.Write(CADDocument.Serializer().Serialize(t));if(s.Strength!=null){using(var w=new StreamWriter(zip.CreateEntry("overload.csv").Open(),new UTF8Encoding(true)))w.Write(TrainStrength.Report(s.Strength,true));using(var w=new StreamWriter(zip.CreateEntry("loads.json").Open(),Encoding.UTF8))w.Write(CADDocument.Serializer().Serialize(s.Strength));}using(var w=new StreamWriter(zip.CreateEntry("construction_status.txt").Open(),Encoding.UTF8))w.Write("ReadyForManufacture=false. Preliminary geometry. Bearings and threaded rods/nuts are purchased parts represented by envelopes, not approved catalogue selections. Thread, fits, retention, strength, fatigue, life and heat require verification.");}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
}}
